// Apply appearance before the first paint, including in the desktop CSP.
(()=>{let theme='system',dark=matchMedia('(prefers-color-scheme: dark)').matches;try{theme=JSON.parse(localStorage.getItem('circuit-lab-experiments-v2'))?.settings?.theme??'system';}catch{}try{if(typeof globalThis.CircuitSystemTheme?.isDark==='function'){dark=CircuitSystemTheme.isDark();globalThis.circuitLabNativeDark=dark;}}catch{}document.documentElement.dataset.theme=theme==='dark'||theme!=='light'&&dark?'dark':'light';})();
